                    writer.WriteNumber("player_rank_initial_calibration_games", lastRankedMatch.PlayerRankInitialCalibrationGamesOption.Value!.Value);
                else
                    writer.WriteNull("player_rank_initial_calibration_games");

            if (lastRankedMatch.PlayerRankInitialDemotionProtectionGamesOption.IsSet)
                if (lastRankedMatch.PlayerRankInitialDemotionProtectionGamesOption.Value != null)
                    writer.WriteNumber("player_rank_initial_demotion_protection_games", lastRankedMatch.PlayerRankInitialDemotionProtectionGamesOption.Value!.Value);
                else
                    writer.WriteNull("player_rank_initial_demotion_protection_games");

            if (lastRankedMatch.PlayerRankInitialFlatProgressOption.IsSet)
                if (lastRankedMatch.PlayerRankInitialFlatProgressOption.Value != null)
                    writer.WriteNumber("player_rank_initial_flat_progress", lastRankedMatch.PlayerRankInitialFlatProgressOption.Value!.Value);
                else
                    writer.WriteNull("player_rank_initial_flat_progress");

            if (lastRankedMatch.PlayerRankInitialWinStreakOption.IsSet)
                if (lastRankedMatch.PlayerRankInitialWinStreakOption.Value != null)
                    writer.WriteNumber("player_rank_initial_win_streak", lastRankedMatch.PlayerRankInitialWinStreakOption.Value!.Value);
                else
                    writer.WriteNull("player_rank_initial_win_streak");

            if (lastRankedMatch.RankIntervalOption.IsSet)
                if (lastRankedMatch.RankIntervalOption.Value != null)
                    writer.WriteNumber("rank_interval", lastRankedMatch.RankIntervalOption.Value!.Value);
                else
                    writer.WriteNull("rank_interval");
        }
    }
}
